/* Session dashboard and offline replay terminal. No live orders or generated prices. */
(() => {
  'use strict';
  const E=window.BacktestEngine, $=s=>document.querySelector(s), app=$('#bt-app');
  const ROOT=window.OP_FLASK ? '/static/' : '../';
  const esc=v=>String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const cash=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
  const num=(n,d=2)=>Number.isFinite(n) ? n.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}) : '—';
  const pct=n=>Number.isFinite(n) ? (n>0?'+':'')+num(n)+'%' : '—';
  const price=n=>num(n,n && n<20 ? 5 : 2);
  const date=t=>new Date(t*1000).toISOString().slice(0,16).replace('T',' ');
  const tone=n=>n<0?'bt-down':n>0?'bt-up':'';
  const pf=n=>n===Infinity?'∞':num(n);
  let key='onepercent:backtesting:v1:guest', owner='Guest', state={sessions:[],strategies:[]};
  let active=null, timer=null, speed=1, barsVisible=80, movingAverage=false, lineTool=false, chartView=null, saveBlocked=false;
  let query='', sort='newest', instrument='', layout='grid', toastTimer, busy=false, ready=false;
  const localMT5=location.hostname==='localhost' && location.port==='8765';
  let brokerPairs=[], sharedPairs=[], sync=null, ownerGeneration=0;
  const marketAPI=String(window.THEONEPERCENT_MARKET_API || '').replace(/\/$/,'');
  async function sharedJSON(path){if(!marketAPI || localMT5)throw Error('Shared history is not configured here.');const r=await fetch(marketAPI+path,{signal:AbortSignal.timeout(45000)});const body=await r.json();if(!r.ok)throw Error(body.detail || 'Shared history is unavailable.');return body;}
  async function brokerJSON(path){const r=await fetch(path,{signal:AbortSignal.timeout(20000)});const body=await r.json();if(!r.ok)throw Error(body.detail || 'MT5 history unavailable.');return body;}
  const datasets=[
    {id:'eurusd',symbol:'EURUSD',interval:'1H',file:'EURUSD_1H.csv',label:'EURUSD · 1 hour · Dec 2023–Apr 2024',quantity:10000},
    {id:'btcusd',symbol:'BTCUSD',interval:'1D',file:'BTCUSD_1D.csv',label:'BTCUSD · daily · Sep 2020–Mar 2026',quantity:0.1},
    {id:'gbpusd',symbol:'GBPUSD',interval:'1D',file:'GBPUSD_1D.csv',label:'GBPUSD · daily · Dec 2023–Sep 2026',quantity:10000}
  ];
  function toast(message) { clearTimeout(toastTimer); $('#bt-toast').textContent=message; $('#bt-toast').hidden=false; toastTimer=setTimeout(()=>$('#bt-toast').hidden=true,5000); }
  function backup() { return {schema:1,sessions:state.sessions.map(E.snapshot),strategies:state.strategies}; }
  function persist() {
    if(saveBlocked) return false;
    try { localStorage.setItem(key,JSON.stringify(backup())); $('#bt-storage-label').textContent=owner+' · saved in this browser';if(sync)sync.schedule(); return true; }
    catch (_) { $('#bt-storage-label').textContent='Storage unavailable · export a backup'; toast('Could not save in browser storage. Export a workspace backup before leaving.'); return false; }
  }
  function load(raw) {
    if (!raw || raw.schema!==1 || !Array.isArray(raw.sessions) || raw.sessions.length>50 || !Array.isArray(raw.strategies) || raw.strategies.length>100) throw Error('This is not a supported workspace backup.');
    const sessions=raw.sessions.map(E.restore);
    if (new Set(sessions.map(s=>s.id)).size!==sessions.length) throw Error('Duplicate saved session IDs.');
    const strategies=raw.strategies.map(s=>({id:String(s.id || E.id()).slice(0,100),name:String(s.name || 'Untitled').slice(0,80),setup:String(s.setup || '').slice(0,2000),entry:String(s.entry || '').slice(0,2000),exit:String(s.exit || '').slice(0,2000),risk:String(s.risk || '').slice(0,2000),createdAt:String(s.createdAt || '')}));
    return {sessions,strategies};
  }
  function download(name,body,type='application/json') { const url=URL.createObjectURL(new Blob([body],{type})), a=document.createElement('a'); a.href=url; a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(url),1000); }
  function sessionStrategy(s) { return s.strategySnapshot?.name || strategyName(s.strategyId); }
  function strategyName(id) { return state.strategies.find(s=>s.id===id)?.name || 'Unassigned strategy'; }
  function current() { return state.sessions.find(s=>s.id===active); }
  function pause(save=true) { if (timer) clearInterval(timer); timer=null; if (save && ready) persist(); const b=$('#bt-play'); if(b) b.textContent='▶ Play'; }
  function modal(title,body) { pause(); $('#bt-dialog-body').innerHTML='<div class="bt-dialog-head"><h2 id="bt-dialog-title">'+esc(title)+'</h2><button class="bt-button small" data-close-dialog aria-label="Close dialog">✕</button></div>'+body; $('#bt-dialog').showModal(); }
  function spark(s,large=false) {
    const values=s.equity.map(x=>x.value), count=Math.min(100,values.length), points=Array.from({length:count},(_,i)=>values[Math.round(i*(values.length-1)/Math.max(1,count-1))]);
    const lo=Math.min(...points,s.startBalance),hi=Math.max(...points,s.startBalance), span=hi-lo||s.startBalance*.01||1;
    const path=points.map((v,i)=>(i?'L':'M')+(i/Math.max(1,points.length-1)*400).toFixed(1)+','+(74-(v-lo)/span*58).toFixed(1)).join(' ');
    const color=E.metrics(s).equity>=s.startBalance?'var(--bt-up)':'var(--bt-down)';
    return '<svg class="'+(large?'bt-equity-plot':'bt-spark')+'" viewBox="0 0 400 85" preserveAspectRatio="none" role="img" aria-label="Mark-to-market equity curve"><path d="'+path+' L400,85 L0,85Z" fill="'+color+'" opacity=".08"/><path d="'+path+'" fill="none" stroke="'+color+'" stroke-width="1.6" vector-effect="non-scaling-stroke"/></svg>';
  }
  function tutorial() { return '<article class="bt-card bt-tutorial"><span class="bt-eyebrow">A BETTER WAY TO PRACTICE</span><h2>One candle.<br>One decision.</h2><p>Replay a market without seeing the next move. Write your rules, place a simulated trade, then review what actually happened.</p><div class="bt-tutorial-chart"><svg viewBox="0 0 280 90" aria-hidden="true"><path d="M0 75L20 68L38 76L53 43L72 54L92 31L112 39L132 15L152 29L174 22L195 48L214 35L237 12L258 20L280 4" fill="none" stroke="var(--bt-up)" stroke-width="2"/><path d="M0 85H280" stroke="var(--bt-line)"/></svg></div><button class="bt-button primary" data-guide>▷ How replay works</button></article>'; }
  function filtered() {
    return state.sessions.filter(s=>(!instrument || s.symbol===instrument) && (s.name+' '+s.symbol+' '+sessionStrategy(s)).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='return'?E.metrics(b).returnPct-E.metrics(a).returnPct:sort==='oldest'?a.createdAt.localeCompare(b.createdAt):b.createdAt.localeCompare(a.createdAt));
  }
  function card(s) {
    const m=E.metrics(s), progress=Math.round((s.cursor-s.initialCursor)/(s.candles.length-1-s.initialCursor)*100);
    return '<article class="bt-card"><div class="bt-card-inner"><div class="bt-card-top"><div><h2>'+esc(s.name)+'</h2><div class="bt-meta">'+esc(s.symbol)+' · '+esc(s.interval)+'<br>'+esc(sessionStrategy(s))+'</div></div><div class="bt-card-actions"><button class="bt-button small" data-open="'+esc(s.id)+'">▶ Continue</button><button class="bt-button small" data-stats="'+esc(s.id)+'" aria-label="Statistics for '+esc(s.name)+'">↗ Stats</button></div></div><div><div class="bt-card-return '+tone(m.returnPct)+'">'+pct(m.returnPct)+'</div><div class="bt-card-money">'+cash(m.equity-s.startBalance)+' · marked equity</div></div><div class="bt-card-metrics"><div><b>'+m.trades+'</b><small>CLOSED</small></div><div><b>'+ (m.winRate==null?'—':num(m.winRate,0)+'%')+'</b><small>WIN RATE</small></div><div><b>'+num(m.drawdown,1)+'%</b><small>MAX DD</small></div><div><b>'+pf(m.profitFactor)+'</b><small>NET PF</small></div></div></div>'+spark(s)+'<small class="bt-card-source">'+esc(s.source)+'</small><div class="bt-card-foot"><span>'+progress+'% replayed · '+date(s.candles[s.cursor].t).slice(0,10)+'</span><button class="bt-text-button" data-delete-session="'+esc(s.id)+'" aria-label="Delete '+esc(s.name)+'">Delete</button></div></article>';
  }
  function renderCards() { $('#bt-cards').innerHTML=(layout==='grid'?tutorial():'')+filtered().map(card).join('')+(!filtered().length?'<div class="bt-empty"><h2>'+ (state.sessions.length?'No matching sessions':'Your research starts here')+'</h2><p>'+(state.sessions.length?'Try a different search or instrument.':'Create a session from an archived dataset or your own OHLC CSV. No results are prefilled.')+'</p><button class="bt-button primary" data-new-session>＋ New session</button></div>':''); }
  function dashboard() {
    const total=state.sessions.reduce((n,s)=>n+s.trades.length,0), started=state.sessions.filter(s=>s.cursor>s.initialCursor).length;
    app.innerHTML='<header class="bt-heading"><div><div class="bt-eyebrow">THE1% / BACKTESTING</div><h1>Your sessions<span style="color:var(--bt-accent)">.</span></h1><p>A quiet place to test an idea before you trust it.</p></div><div class="bt-actions"><button class="bt-button" data-new-strategy>＋ New strategy</button><button class="bt-button primary" data-new-session>＋ New session</button></div></header><div class="bt-overview"><div><small>RESEARCH SESSIONS</small><b>'+state.sessions.length+'</b><span>'+started+' with replay progress</span></div><div><small>SIMULATED TRADES</small><b>'+total+'</b><span>Closed across your sessions</span></div><div><small>STRATEGY PLAYBOOKS</small><b>'+state.strategies.length+'</b><span>Written, repeatable rules</span></div><div><small>RESEARCH MODE</small><b style="font-size:18px">Bar replay</b><span>Historical data · simulated fills</span></div></div><div class="bt-toolbar"><div class="bt-filters"><input id="bt-search" class="bt-input" type="search" aria-label="Search sessions" placeholder="Search sessions or strategies…" value="'+esc(query)+'"><select id="bt-sort" class="bt-select" aria-label="Sort sessions"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="name">Name A–Z</option><option value="return">Highest return</option></select><select id="bt-instrument" class="bt-select" aria-label="Filter instrument"><option value="">All instruments</option>'+[...new Set(state.sessions.map(s=>s.symbol))].map(symbol=>'<option>'+esc(symbol)+'</option>').join('')+'</select></div><div class="bt-view" aria-label="Session layout"><button data-layout="grid" class="'+(layout==='grid'?'active':'')+'">▦ Grid</button><button data-layout="list" class="'+(layout==='list'?'active':'')+'">☷ List</button></div></div><div id="bt-cards" class="bt-grid '+(layout==='list'?'list':'')+'"></div><p class="bt-local-note">Sign in to save sessions online and resume on another device. Guests keep their sessions in this browser. Export a backup before clearing browser data. P&L is simulated in USD and excludes financing, margin and liquidation models.</p>';
    $('#bt-sort').value=sort; $('#bt-instrument').value=instrument;
    $('#bt-search').oninput=e=>{query=e.target.value;renderCards();};
    $('#bt-sort').onchange=e=>{sort=e.target.value;renderCards();};
    $('#bt-instrument').onchange=e=>{instrument=e.target.value;renderCards();};
    renderCards();
  }
  function strategies() {
    app.innerHTML='<header class="bt-heading"><div><div class="bt-eyebrow">YOUR RESEARCH PLAYBOOK</div><h1>Rules before results.</h1><p>Define the setup, entry, invalidation and risk before pressing play.</p></div><button class="bt-button primary" data-new-strategy>＋ New strategy</button></header><div class="bt-grid">'+state.strategies.map(s=>'<article class="bt-card"><div style="padding:24px"><div class="bt-eyebrow">STRATEGY / '+state.sessions.filter(x=>x.strategyId===s.id).length+' SESSIONS</div><h2 style="margin-top:12px">'+esc(s.name)+'</h2><p class="bt-local-note">'+esc(s.setup || 'No setup notes yet.')+'</p><div class="bt-actions"><button class="bt-button small" data-edit-strategy="'+esc(s.id)+'">Edit rules</button><button class="bt-button small" data-strategy-session="'+esc(s.id)+'">Test strategy</button><button class="bt-text-button" data-delete-strategy="'+esc(s.id)+'">Delete</button></div></div></article>').join('')+'</div>'+(!state.strategies.length?'<div class="bt-empty"><h2>No playbooks yet</h2><p>Write a hypothesis you can reproduce. Strategy notes organize your manual testing; they do not generate automatic signals.</p><button class="bt-button primary" data-new-strategy>＋ Create a strategy</button></div>':'');
  }
  function sessionForm(strategyId='') {
    if(state.sessions.length>=50) return toast('This browser workspace supports 50 sessions. Export and remove an older session first.');
    modal('Start a replay session','<p>Backtest on your phone or computer using an included sample archive, shared forex history, or your own CSV. MT5 is optional. Orders in this workspace are simulated.</p><form id="bt-new-form"><div class="bt-form-grid"><label class="bt-field full"><span>Session name</span><input class="bt-input" name="name" required maxlength="80" placeholder="London breakout · first research sample"></label><label class="bt-field full"><span>Dataset</span><select class="bt-select" name="dataset" id="bt-dataset">'+datasets.map(d=>'<option value="'+d.id+'">'+esc(d.label)+' · archived sample</option>').join('')+'<option value="shared">Shared forex history · website feed</option><option value="custom">Import OHLC CSV…</option><option value="mt5">MT5 broker · all available forex pairs</option></select><small>Bundled archives come from the existing project’s Yahoo Finance/yfinance cache. Historical sample, not a live feed.</small></label><div id="bt-shared-field" class="bt-field full" hidden><span>Shared forex history · works on phone and PC</span><p id="bt-shared-status" role="status">Checking the website feed…</p><label class="bt-field"><span>Search pairs</span><input id="bt-shared-search" class="bt-input" type="search" placeholder="EUR, JPY, GBP…"></label><label class="bt-field"><span>Forex pair</span><select id="bt-shared-pair" class="bt-select"><option value="">No provider connected yet</option></select></label><label class="bt-field"><span>Timeframe</span><select id="bt-shared-interval" class="bt-select"><option>1m</option><option>5m</option><option>15m</option><option>30m</option><option selected>1H</option><option>4H</option><option>1D</option><option>1W</option></select></label><label class="bt-field"><span>Candles (60–5,000)</span><input id="bt-shared-count" class="bt-input" type="number" min="60" max="5000" value="1000"></label><label class="bt-field"><span>History ends at (optional, UTC)</span><input id="bt-shared-end" class="bt-input" type="datetime-local"><small>Leave blank for the latest closed history. Provider coverage determines available dates.</small></label></div><div id="bt-mt5-field" class="bt-field full" hidden><span>MT5 broker history</span><p id="bt-mt5-status" role="status"></p><a class="bt-button small" id="bt-open-bridge" href="http://localhost:8765/pages/backtesting.html#sessions" target="_blank" rel="noopener">Open local MT5 workspace ↗</a><label class="bt-field"><span>Search available forex pairs</span><input id="bt-pair-search" class="bt-input" type="search" placeholder="EUR, JPY, GBP…"></label><label class="bt-field"><span>Broker pair</span><select id="bt-pair" class="bt-select"><option value="">Connect MT5 to load pairs</option></select></label><label class="bt-field"><span>History interval</span><select id="bt-broker-interval" class="bt-select"><option>1m</option><option>5m</option><option>15m</option><option>30m</option><option selected>1H</option><option>4H</option><option>1D</option><option>1W</option></select></label><label class="bt-field"><span>Closed candles to request (60–10,000)</span><input id="bt-broker-count" class="bt-input" type="number" min="60" max="10000" value="2000"></label><small>History depth depends on your terminal. This existing bridge connects to Exness MT5. Broker data never leaves this local workspace.</small><details><summary>MT5 setup instructions</summary><p>Open your Exness MT5 terminal. From the project folder run:</p><p><code>python -m pip install -r backend/requirements.txt MetaTrader5</code></p><p><code>python -m uvicorn backend.local_mt5_bridge:app --host localhost --port 8765</code></p><p>Keep the bridge running, then open the local workspace above. History depth depends on your broker and MT5 settings.</p></details></div><label id="bt-csv-field" class="bt-field full" hidden><span>CSV file (max 2.5 MB / 10,000 candles)</span><input name="csv" class="bt-input" type="file" accept=".csv,text/csv"><small>Columns: Date/Datetime/Time, Open, High, Low, Close. ISO timestamps or Unix seconds/milliseconds. Timezone-free dates use UTC.</small></label><label class="bt-field"><span>Instrument label</span><input name="symbol" class="bt-input" value="EURUSD" required maxlength="64"></label><label class="bt-field"><span>Dataset interval label</span><input name="interval" class="bt-input" value="1H" required maxlength="12"><small>Label only; candles are not resampled.</small></label><label class="bt-field"><span>Starting balance (USD)</span><input name="startBalance" class="bt-input" type="number" value="10000" min="1" max="1000000000" required></label><label class="bt-field"><span>Cash multiplier</span><input name="multiplier" class="bt-input" type="number" value="1" min="0.00000001" max="1000000000" step="any" required><small>USD per 1.0 price move per unit. Verify contract and FX conversion.</small></label><label class="bt-field"><span>Fee per unit, per side (USD)</span><input name="fee" class="bt-input" type="number" value="0" min="0" step="any" required></label><label class="bt-field"><span>Adverse slippage (price units)</span><input name="slippage" class="bt-input" type="number" value="0" min="0" step="any" required></label><label class="bt-field full"><span>Strategy</span><select name="strategyId" class="bt-select"><option value="">Unassigned</option>'+state.strategies.map(s=>'<option value="'+esc(s.id)+'" '+(s.id===strategyId?'selected':'')+'>'+esc(s.name)+'</option>').join('')+'</select></label><label class="bt-field full"><span>Replay starts after (optional, UTC)</span><input name="start" class="bt-input" type="datetime-local"><small>Leave blank to begin with up to 100 context candles. Choose a date inside the dataset with at least 30 preceding candles.</small></label></div><div id="bt-form-error" class="bt-error" role="alert"></div><div class="bt-actions"><button type="button" class="bt-button" data-close-dialog>Cancel</button><button type="submit" class="bt-button primary">Create session →</button></div></form>');
    const form=$('#bt-new-form');
    function selectShared(){const pair=sharedPairs.find(p=>p.symbol===$('#bt-shared-pair').value);if(!pair)return;form.elements.symbol.value=pair.symbol;form.elements.interval.value=$('#bt-shared-interval').value;form.elements.multiplier.value=pair.quote_asset==='USD'?'1':'';form.elements.multiplier.placeholder=pair.quote_asset==='USD'?'1':'Enter fixed USD conversion per price unit';}
    function filterShared(){const q=$('#bt-shared-search').value.toLowerCase();$('#bt-shared-pair').innerHTML=sharedPairs.filter(p=>p.symbol.toLowerCase().includes(q)).map(p=>'<option>'+esc(p.symbol)+'</option>').join('');selectShared();}
    $('#bt-shared-search').oninput=filterShared;$('#bt-shared-pair').onchange=selectShared;$('#bt-shared-interval').onchange=()=>form.elements.interval.value=$('#bt-shared-interval').value;
    async function loadShared(){const status=$('#bt-shared-status');sharedPairs=[];try{const rows=[];let offset=0;while(true){const result=await sharedJSON('/api/backtesting/catalog?limit=100&offset='+offset);if(result.status!=='configured')throw Error(result.message || 'Shared forex history is not connected yet. Choose an included archive to preview.');rows.push(...result.data);if(!result.has_more)break;if(!result.data.length || offset>100000)throw Error('Incomplete provider catalogue.');offset+=result.data.length;}if(!form.isConnected)return;sharedPairs=rows;filterShared();status.textContent=rows.length+' forex pairs available. History coverage depends on the provider.';}catch(error){if(form.isConnected){$('#bt-shared-pair').innerHTML='<option value="">No shared pairs available</option>';status.textContent=error.message+' Included sample archives work without MT5.';}}}
    function selectPair(){const pair=brokerPairs.find(p=>p.symbol===$('#bt-pair').value);if(!pair)return;form.elements.symbol.value=pair.symbol;form.elements.interval.value=$('#bt-broker-interval').value;form.elements.multiplier.value=pair.quote_asset==='USD'?'1':'';form.elements.multiplier.placeholder=pair.quote_asset==='USD'?'1':'Enter USD conversion per price unit';}
    function filterPairs(){const q=$('#bt-pair-search').value.toLowerCase();$('#bt-pair').innerHTML=brokerPairs.filter(p=>(p.symbol+' '+p.name).toLowerCase().includes(q)).map(p=>'<option value="'+esc(p.symbol)+'">'+esc(p.symbol+' · '+p.name)+'</option>').join('');selectPair();}
    $('#bt-pair-search').oninput=filterPairs;$('#bt-pair').onchange=selectPair;$('#bt-broker-interval').onchange=()=>{form.elements.interval.value=$('#bt-broker-interval').value;};
    $('#bt-dataset').onchange=async e=>{
      const custom=e.target.value==='custom',mt5=e.target.value==='mt5',shared=e.target.value==='shared',d=datasets.find(d=>d.id===e.target.value);
      $('#bt-csv-field').hidden=!custom;$('#bt-mt5-field').hidden=!mt5;$('#bt-shared-field').hidden=!shared;for(const input of $('#bt-shared-field').querySelectorAll('input,select'))input.disabled=!shared;if(shared)loadShared();
      for(const input of $('#bt-mt5-field').querySelectorAll('input,select'))input.disabled=!mt5||!localMT5;
      form.elements.symbol.readOnly=!custom;form.elements.interval.readOnly=!custom;
      if(d){form.elements.symbol.value=d.symbol;form.elements.interval.value=d.interval;form.elements.multiplier.value='1';}
      if(!mt5)return;
      $('#bt-open-bridge').hidden=localMT5;
      const status=$('#bt-mt5-status');status.textContent=localMT5?'Reading broker catalogue…':'Start the local MT5 bridge, then open the local workspace using the button below. See the MT5 setup guide.';
      if(!localMT5)return;
      try{const rows=[];let offset=0;while(true){const result=await brokerJSON('/api/instruments?market=forex&limit=100&offset='+offset);rows.push(...result.data);if(!result.has_more)break;if(!result.data.length)throw Error('Incomplete broker catalogue.');offset+=result.data.length;if(offset>100000)throw Error('Broker catalogue is too large.');}if(!form.isConnected)return;brokerPairs=rows;filterPairs();status.textContent=rows.length+' forex instruments available from your broker. History availability is checked when creating the session.';}
      catch(error){status.textContent=error.message;}
    };
    $('#bt-dataset').dispatchEvent(new Event('change'));
    $('#bt-new-form').onsubmit=async e=>{
      e.preventDefault();if(busy)return;busy=true;const form=e.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Reading candles…';
      try {
        const requestKey=key;const f=new FormData(form),d=datasets.find(d=>d.id===f.get('dataset'));let text,source,bars;
        if(f.get('dataset')==='shared'){const symbol=$('#bt-shared-pair').value;if(!sharedPairs.some(p=>p.symbol===symbol))throw Error('Choose an available shared pair, or select an included sample archive.');const result=await sharedJSON('/api/backtesting/candles?'+new URLSearchParams({symbol,interval:$('#bt-shared-interval').value,limit:$('#bt-shared-count').value,end:$('#bt-shared-end').value}));if(result.symbol!==symbol || result.interval!==$('#bt-shared-interval').value || !result.closed_only)throw Error('The shared feed returned an unexpected pair or interval.');bars=E.validateBars(result.candles);source=result.source;}
        else if(f.get('dataset')==='mt5'){if(!localMT5)throw Error('Open the local MT5 workspace to use broker history.');const symbol=$('#bt-pair').value;if(!brokerPairs.some(p=>p.symbol===symbol))throw Error('Select an available broker pair.');const result=await brokerJSON('/api/backtesting/candles?'+new URLSearchParams({symbol,interval:$('#bt-broker-interval').value,limit:$('#bt-broker-count').value}));bars=E.validateBars(result.candles);source=result.source+' · closed candles';}
        else if(d){const response=await fetch(ROOT+'assets/backtesting/data/'+d.file);if(!response.ok)throw Error('The archived dataset could not be loaded.');text=await response.text();source='Archived sample · Yahoo Finance via project cache';}
        else{const file=form.elements.csv.files[0];if(!file)throw Error('Select a CSV file.');if(file.size>2500000)throw Error('CSV must be smaller than 2.5 MB.');text=await file.text();source='Imported CSV · '+file.name;}
        if(!$('#bt-dialog').open || form!==$('#bt-new-form'))return;
        if(key!==requestKey || !form.isConnected)throw Error('Workspace changed while reading the dataset. Start again.');
        bars=bars || E.parseCSV(text);let cursor;
        if(f.get('start')){const t=Date.parse(f.get('start')+'Z')/1000;cursor=bars.findIndex(b=>b.t>=t);if(cursor<30 || cursor>=bars.length-1)throw Error('Choose a date inside the dataset with 30 earlier candles and at least one candle remaining.');cursor--;}
        const s=E.createSession({...Object.fromEntries(f),source,cursor,strategySnapshot:state.strategies.find(s=>s.id===f.get('strategyId'))},bars);state.sessions.push(s);const saved=persist();$('#bt-dialog').close();location.hash='session/'+s.id;toast(saved?'Session created. Future candles are hidden.':'Session created for this tab. Export a backup to keep it.');
      } catch(error){if(form.isConnected)form.querySelector('#bt-form-error').textContent=error.message;else toast(error.message);} finally{busy=false;button.disabled=false;button.textContent='Create session →';}
    };
  }
  function strategyForm(existing=null) {
    modal(existing?'Edit strategy':'Create a strategy','<p>A written playbook for manual testing. Keep the rules fixed within a research sample.</p><form id="bt-strategy-form"><div class="bt-form-grid"><label class="bt-field full"><span>Strategy name</span><input name="name" class="bt-input" maxlength="80" required value="'+esc(existing?.name || '')+'"></label>'+[['setup','Market context & setup'],['entry','Entry trigger'],['exit','Invalidation & exits'],['risk','Risk rules & exclusions']].map(([key,label])=>'<label class="bt-field full"><span>'+label+'</span><textarea name="'+key+'" class="bt-textarea" maxlength="2000" rows="2" required>'+esc(existing?.[key] || '')+'</textarea></label>').join('')+'</div><div class="bt-actions"><button class="bt-button" type="button" data-close-dialog>Cancel</button><button class="bt-button primary" type="submit">Save strategy</button></div></form>');
    $('#bt-strategy-form').onsubmit=e=>{e.preventDefault();if(!existing && state.strategies.length>=100)return toast('Limit of 100 strategies reached.');const s={...Object.fromEntries(new FormData(e.currentTarget)),id:existing?.id || E.id(),createdAt:existing?.createdAt || new Date().toISOString()};if(existing)state.strategies=state.strategies.map(x=>x.id===s.id?s:x);else state.strategies.push(s);persist();$('#bt-dialog').close();location.hash='strategies';route();};
  }
  function guide() {
    modal('How replay works','<p>Practice decisions one closed candle at a time. This is a manual simulation, not evidence that a strategy will make money.</p><ol class="bt-guide-steps"><li>Create a session and verify the dataset, cash multiplier and costs.</li><li>Write your hypothesis before the next bar is revealed.</li><li>Queue a market, limit or stop order with a protective stop and target.</li><li>Press Next or Play. Market orders fill at the next candle open, with adverse slippage. Limits can remain unfilled.</li><li>If a candle touches both stop and target, the stop wins. A target is not awarded on an uncertain intrabar entry candle.</li><li>Use Stats to review net results and marked-to-market drawdown. Export trades and back up your sessions.</li></ol><p>Fees are charged per unit on entry and exit. Slippage affects market/stop fills; target limits fill at their level. There is no spread, financing, margin, currency-conversion or liquidation model beyond your supplied cash multiplier and costs. No backward replay after a decision: restart as a new session for another attempt.</p><video controls preload="none" poster="'+ROOT+'assets/academy/video/backtesting-poster.jpg"><source src="'+ROOT+'assets/academy/video/backtesting-summary.mp4" type="video/mp4"></video><p><a href="'+ROOT+'assets/academy/video/backtesting-transcript.txt">Read the video transcript</a></p>');
  }
  function tradesTable(s) {
    return '<div class="bt-table-wrap"><table class="bt-table"><thead><tr><th>Side / units</th><th>Entry (UTC)</th><th>Entry price</th><th>Exit price</th><th>Net P&L</th><th>Net R</th><th>Exit reason</th></tr></thead><tbody>'+s.trades.slice().reverse().map(t=>'<tr><td>'+esc(t.side.toUpperCase())+' / '+num(t.quantity,4)+'</td><td>'+date(t.entryTime)+'</td><td>'+price(t.entry)+'</td><td>'+price(t.exit)+'</td><td class="'+tone(t.pnl)+'">'+cash(t.pnl)+'</td><td>'+num(t.r)+'</td><td>'+esc(t.reason)+'</td></tr>').join('')+(!s.trades.length?'<tr><td colspan="7" class="bt-table-empty">No closed trades. Queue an order and advance the replay.</td></tr>':'')+'</tbody></table></div>';
  }
  function stats(s) {
    const m=E.metrics(s);
    modal('Session statistics','<p>'+esc(s.name)+' · '+esc(s.symbol)+' · '+esc(s.interval)+'<br>Results are simulated, after your configured fees and slippage.</p><div class="bt-overview"><div><small>NET REALIZED</small><b style="font-size:16px" class="'+tone(m.realized)+'">'+cash(m.realized)+'</b></div><div><small>WIN RATE</small><b>'+ (m.winRate==null?'—':num(m.winRate,1)+'%')+'</b></div><div><small>MAX EQUITY DD</small><b>'+num(m.drawdown,1)+'%</b></div><div><small>NET PROFIT FACTOR</small><b>'+pf(m.profitFactor)+'</b></div></div>'+spark(s,true)+'<p>'+m.wins+' wins · '+m.losses+' losses · '+m.breakeven+' breakeven · '+m.trades+' closed trades<br>Average net outcome: '+(m.expectancy==null?'—':cash(m.expectancy))+' / trade. Unrealized: '+cash(m.unrealized)+'.<br>Drawdown uses marked equity at revealed candle closes, not intrabar lows. Open-position fees are reflected in equity.</p>'+tradesTable(s)+'<div class="bt-actions"><button class="bt-button" data-export-trades="'+esc(s.id)+'">↓ Export trades CSV</button><button class="bt-button primary" data-open="'+esc(s.id)+'">Continue replay →</button></div>');
  }
  function sessionView(s) {
    active=s.id;lineTool=false;
    app.innerHTML='<header class="bt-session-heading"><div class="bt-session-name"><a class="bt-button small" href="#sessions" aria-label="Back to sessions">←</a><div><h1>'+esc(s.name)+'</h1><p>'+esc(s.symbol)+' / '+esc(s.interval)+' / '+esc(sessionStrategy(s))+'</p></div></div><div class="bt-replay-controls"><button id="bt-play" class="bt-button small">▶ Play</button><button id="bt-next" class="bt-button small">Next ▷</button><select id="bt-speed" class="bt-select" aria-label="Replay speed"><option value="1">1 bar / sec</option><option value="2">2 bars / sec</option><option value="5">5 bars / sec</option><option value="10">10 bars / sec</option></select><button class="bt-button small" id="bt-go">Go to…</button><button class="bt-button small" id="bt-rules">Rules</button><button class="bt-button small" data-stats="'+esc(s.id)+'">↗ Stats</button></div></header><div class="bt-session-stats" id="bt-live-stats"></div><div id="bt-session-notice" class="bt-notice" hidden></div><div class="bt-terminal"><section class="bt-chart-wrap" aria-label="Historical candle replay"><div class="bt-chart-toolbar"><div><b>'+esc(s.symbol)+'</b><span>'+esc(s.interval)+' · closed candles only</span></div><div class="bt-chart-tools"><button id="bt-ma" class="bt-button small '+(movingAverage?'active':'')+'">SMA 20</button><button id="bt-line" class="bt-button small">＋ Level</button><button id="bt-clear-lines" class="bt-button small">Clear levels</button><button id="bt-zoom-in" class="bt-button small" aria-label="Zoom in">＋</button><button id="bt-zoom-out" class="bt-button small" aria-label="Zoom out">−</button></div></div><div class="bt-canvas-box"><div id="bt-chart" class="bt-canvas" role="img" aria-label="Revealed historical candlesticks. The latest candle OHLC is shown in text above the chart."></div><div id="bt-readout" class="bt-chart-readout"></div></div><div class="bt-chart-time"><span id="bt-clock"></span><span id="bt-progress"></span></div><p class="bt-model-note"><a href="https://www.tradingview.com/" target="_blank" rel="noopener">TradingView Lightweight Charts™</a> · '+esc(s.source)+' · Future candles hidden. Space: play/pause · →: next bar. Draw levels by choosing + Level and clicking the chart.</p></section><aside class="bt-ticket"><h2>Simulated order</h2><p class="bt-local-note" style="margin:0 0 14px">One position at a time · '+esc(s.symbol)+'</p><form id="bt-order-form"><label class="bt-field"><span>Side</span><select name="side" class="bt-select"><option value="long">Buy / long</option><option value="short">Sell / short</option></select></label><label class="bt-field"><span>Order type</span><select name="type" class="bt-select"><option value="market">Market · next open</option><option value="limit">Limit</option><option value="stop">Stop entry</option></select></label><label class="bt-field" id="bt-entry-field" hidden><span>Entry / trigger price</span><input name="entry" class="bt-input" type="number" step="any" min="0.00000001"></label><label class="bt-field"><span>Quantity (units / contracts)</span><input name="quantity" class="bt-input" type="number" step="any" min="0.00000001" value="'+(s.symbol.endsWith('USD') && s.symbol.length===6 && s.symbol!=='BTCUSD'?10000:s.symbol==='BTCUSD'?.1:1)+'" required></label><label class="bt-field"><span>Stop loss</span><input name="stop" class="bt-input" type="number" step="any" min="0.00000001" required></label><label class="bt-field"><span>Take profit</span><input name="target" class="bt-input" type="number" step="any" min="0.00000001" required></label><div id="bt-risk-estimate" class="bt-estimate"></div><button class="bt-button primary" id="bt-submit-order" type="submit">Queue order →</button></form><div id="bt-order-error" class="bt-error" role="alert"></div><p class="bt-local-note">Multiplier '+num(s.multiplier,4)+' USD / price unit / quantity unit.<br>Fee '+num(s.fee,4)+' USD per unit per side.<br>Slippage '+price(s.slippage)+' price units.</p></aside></div><div id="bt-position"></div><div id="bt-trade-table"></div><label class="bt-field bt-session-notes"><span>Session notes · save your hypothesis before advancing</span><textarea id="bt-notes" class="bt-textarea" rows="3" maxlength="10000" placeholder="What do I expect, what would invalidate it, and what did I observe?">'+esc(s.notes)+'</textarea></label><div class="bt-actions" style="margin-top:12px"><button class="bt-button small" data-export-trades="'+esc(s.id)+'">↓ Export trades</button><button class="bt-button small" id="bt-restart">Restart as new session</button></div>';
    $('#bt-speed').value=String(speed);
    const form=$('#bt-order-form'),last=s.candles[s.cursor].c;
    form.elements.stop.value=Number((last*.995).toPrecision(8));form.elements.target.value=Number((last*1.01).toPrecision(8));form.elements.entry.value=last;
    form.elements.side.onchange=()=>{const long=form.elements.side.value==='long',last=s.candles[s.cursor].c;form.elements.stop.value=Number((last*(long?.995:1.005)).toPrecision(8));form.elements.target.value=Number((last*(long?1.01:.99)).toPrecision(8));estimate();};
    form.elements.type.onchange=()=>{const market=form.elements.type.value==='market';$('#bt-entry-field').hidden=market;form.elements.entry.disabled=market;estimate();};
    form.elements.type.dispatchEvent(new Event('change'));
    form.oninput=estimate;
    form.onsubmit=e=>{e.preventDefault();pause();try{E.placeOrder(s,Object.fromEntries(new FormData(form)));$('#bt-order-error').textContent='';persist();updateSession();}catch(error){$('#bt-order-error').textContent=error.message;}};
    $('#bt-next').onclick=()=>{pause(false);advance();};
    $('#bt-play').onclick=togglePlay;
    $('#bt-speed').onchange=e=>{speed=Number(e.target.value);if(timer){pause(false);togglePlay();}};
    $('#bt-go').onclick=()=>modal('Advance to a date','<p>Forward only. Every intervening candle is processed, including order fills and stops. Dataset ends '+date(s.candles.at(-1).t)+' UTC.</p><form id="bt-go-form"><label class="bt-field"><span>Target date and time (UTC)</span><input id="bt-go-date" class="bt-input" type="datetime-local" required></label><div id="bt-go-error" class="bt-error" role="alert"></div><div class="bt-actions"><button class="bt-button primary">Advance replay</button></div></form>');
    $('#bt-rules').onclick=()=>{const rules=s.strategySnapshot;modal('Session rules',rules?'<p>Frozen when this session was created. Later playbook edits do not change these rules.</p><h3>'+esc(rules.name)+'</h3>'+['setup','entry','exit','risk'].map(k=>'<h4>'+esc(k.toUpperCase())+'</h4><p>'+esc(rules[k])+'</p>').join(''):'<p>No strategy was assigned when this session was created. Record your hypothesis in the session notes.</p>');};
    $('#bt-ma').onclick=()=>{movingAverage=!movingAverage;$('#bt-ma').classList.toggle('active',movingAverage);drawChart();};
    $('#bt-line').onclick=()=>{lineTool=!lineTool;$('#bt-line').classList.toggle('active',lineTool);toast(lineTool?'Click the chart to add a horizontal level.':'Level tool off.');};
    $('#bt-clear-lines').onclick=()=>{s.drawings=[];persist();drawChart();};
    $('#bt-zoom-in').onclick=()=>{barsVisible=Math.max(25,barsVisible-20);drawChart();};
    $('#bt-zoom-out').onclick=()=>{barsVisible=Math.min(240,barsVisible+20);drawChart();};
    $('#bt-notes').oninput=e=>{s.notes=e.target.value;s.updatedAt=new Date().toISOString();};
    $('#bt-notes').onchange=()=>persist();
    $('#bt-restart').onclick=()=>{if(state.sessions.length>=50)return toast('Export and remove an older session first.');modal('Restart as a new session','<p>Your existing trades and results are preserved. The new attempt starts at the original replay cursor with no trades.</p><div class="bt-actions"><button class="bt-button" data-close-dialog>Cancel</button><button class="bt-button primary" id="bt-confirm-restart">Create fresh attempt</button></div>');$('#bt-confirm-restart').onclick=()=>{const copy=E.createSession({...s,cursor:s.initialCursor,name:s.name+' · new attempt'},s.candles);state.sessions.push(copy);persist();$('#bt-dialog').close();location.hash='session/'+copy.id;};};
    if(chartView)chartView.destroy();
    chartView=new window.BacktestChart($('#bt-chart'),b=>{if(b && $('#bt-readout'))$('#bt-readout').textContent=date(b.t)+' UTC · O '+price(b.o)+' H '+price(b.h)+' L '+price(b.l)+' C '+price(b.c);},value=>{if(!lineTool)return;if(s.drawings.length>=30)return toast('Maximum 30 levels.');s.drawings.push(value);lineTool=false;$('#bt-line').classList.remove('active');persist();drawChart();});
    updateSession();requestAnimationFrame(drawChart);
  }
  function estimate() {
    const s=current(),form=$('#bt-order-form');if(!s || !form)return;
    const entry=form.elements.type.value==='market'?s.candles[s.cursor].c:Number(form.elements.entry.value), q=Number(form.elements.quantity.value),stop=Number(form.elements.stop.value),target=Number(form.elements.target.value);
    if (![entry,q,stop,target].every(n=>Number.isFinite(n) && n>0)) { $('#bt-risk-estimate').textContent='Enter an entry, quantity, stop and target to estimate risk.'; return; }
    const risk=Math.abs(entry-stop)*q*s.multiplier+2*s.fee*q,reward=Math.abs(target-entry)*q*s.multiplier-2*s.fee*q;
    $('#bt-risk-estimate').innerHTML='Indicative risk: '+cash(risk)+'<br>Indicative reward: '+cash(reward)+'<br>Planned R: '+(risk>0?num(reward/risk):'—')+'<br><span style="color:var(--bt-muted)">Uses the last close / requested entry. Actual fills and gaps change risk.</span>';
  }
  function advance() { const s=current();if(!s)return;if(!E.step(s)){pause();return toast('End of dataset.');}persist();updateSession();if(s.cursor===s.candles.length-1)pause(); }
  function togglePlay() { if(timer){pause();return;}const s=current();if(!s || s.cursor===s.candles.length-1)return toast('No more candles remain.');$('#bt-play').textContent='Ⅱ Pause';timer=setInterval(advance,1000/speed); }
  function updateSession() {
    const s=current();if(!s || !$('#bt-chart'))return;const m=E.metrics(s);
    $('#bt-live-stats').innerHTML=[['Starting balance',cash(s.startBalance)],['Current equity',cash(m.equity)],['Win rate',m.winRate==null?'—':num(m.winRate,1)+'%'],['Closed trades',m.trades],['Net realized',cash(m.realized)],['Unrealized',cash(m.unrealized)]].map(([label,value],i)=>'<div><small>'+label+'</small><b class="'+(i>3?tone(i===4?m.realized:m.unrealized):'')+'">'+value+'</b></div>').join('');
    $('#bt-session-notice').hidden=!s.notice;$('#bt-session-notice').textContent=s.notice;
    $('#bt-clock').textContent=date(s.candles[s.cursor].t)+' UTC';$('#bt-progress').textContent=(s.cursor-s.initialCursor)+' / '+(s.candles.length-1-s.initialCursor)+' replay bars';
    $('#bt-next').disabled=s.cursor===s.candles.length-1;$('#bt-submit-order').disabled=!!(s.position || s.pending || s.cursor===s.candles.length-1);
    const p=s.position||s.pending;
    $('#bt-position').innerHTML=p?'<div class="bt-position-bar"><div><b>'+ (s.position?'OPEN POSITION':'PENDING '+p.type.toUpperCase())+' / '+p.side.toUpperCase()+'</b><p>'+num(p.quantity,4)+' units · Entry '+(p.entry?price(p.entry):'next open')+' · SL '+price(p.stop)+' · TP '+price(p.target)+(s.position?' · Marked P&L '+cash(m.unrealized):'')+'</p></div><button class="bt-button small" id="bt-position-action">'+(s.position?(p.closeRequested?'Close queued':'Close next open'):'Cancel order')+'</button></div>':'<div class="bt-position-bar"><span>No open position or queued order.</span><small style="color:var(--bt-muted)">Orders become eligible on the next candle.</small></div>';
    if($('#bt-position-action'))$('#bt-position-action').onclick=()=>{pause();try{if(s.position){if(s.position.closeRequested)return;E.requestClose(s);}else E.cancelOrder(s);persist();updateSession();}catch(e){toast(e.message);}};
    $('#bt-trade-table').innerHTML=tradesTable(s);estimate();drawChart();
  }
  function drawChart() {const s=current();if(s && chartView && $('#bt-chart'))chartView.render(s,movingAverage,barsVisible);}
  function exportTrades(s) {
    const cell=v=>{const text=String(v??'');return '"'+(typeof v==='string' && /^[\s]*[=+@\-]/.test(text)?"'":'')+text.replace(/"/g,'""')+'"';};
    const rows=[['symbol','side','quantity','entry_utc','exit_utc','entry','exit','gross_usd','fees_usd','net_usd','net_r','reason'],...s.trades.map(t=>[s.symbol,t.side,t.quantity,date(t.entryTime),date(t.exitTime),t.entry,t.exit,t.gross,t.fees,t.pnl,t.r,t.reason])];download('backtest-'+s.symbol+'-trades.csv',rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv');
  }
  function route() {
    if(!ready)return;pause();if(chartView){chartView.destroy();chartView=null;}const parts=location.hash.slice(1).split('/');active=null;
    $('#session-count').textContent=state.sessions.length;$('#strategy-count').textContent=state.strategies.length;
    document.querySelectorAll('[data-section]').forEach(a=>a.classList.toggle('active',a.dataset.section===(parts[0]==='strategies'?'strategies':'sessions')));
    if(parts[0]==='session'){const s=state.sessions.find(s=>s.id===parts[1]);if(s)sessionView(s);else{toast('Session not found in this browser workspace.');location.hash='sessions';dashboard();}}
    else if(parts[0]==='strategies')strategies();else dashboard();
  }
  document.addEventListener('click',e=>{
    const b=e.target.closest('button,a');if(!b)return;
    if(b.hasAttribute('data-close-dialog'))$('#bt-dialog').close();
    if(b.hasAttribute('data-new-session'))sessionForm();
    if(b.hasAttribute('data-new-strategy'))strategyForm();
    if(b.hasAttribute('data-guide'))guide();
    if(b.dataset.open){$('#bt-dialog').close();if(location.hash==='#session/'+b.dataset.open)sessionView(state.sessions.find(s=>s.id===b.dataset.open));else location.hash='session/'+b.dataset.open;}
    if(b.dataset.stats){const s=state.sessions.find(s=>s.id===b.dataset.stats);if(s)stats(s);}
    if(b.dataset.layout){layout=b.dataset.layout;dashboard();}
    if(b.dataset.editStrategy)strategyForm(state.strategies.find(s=>s.id===b.dataset.editStrategy));
    if(b.dataset.strategySession)sessionForm(b.dataset.strategySession);
    if(b.dataset.exportTrades){const s=state.sessions.find(s=>s.id===b.dataset.exportTrades);if(s)exportTrades(s);}
    if(b.dataset.deleteSession){const s=state.sessions.find(s=>s.id===b.dataset.deleteSession);modal('Delete this session?','<p>Delete '+esc(s.name)+' and its simulated trades from this browser workspace? Export a backup first if you want to keep it.</p><div class="bt-actions"><button class="bt-button" data-close-dialog>Keep session</button><button id="bt-confirm-delete" class="bt-button danger">Delete session</button></div>');$('#bt-confirm-delete').onclick=()=>{state.sessions=state.sessions.filter(x=>x.id!==s.id);persist();$('#bt-dialog').close();route();};}
    if(b.dataset.deleteStrategy){const id=b.dataset.deleteStrategy;modal('Delete strategy?','<p>Sessions remain available, but this playbook will be removed.</p><div class="bt-actions"><button class="bt-button" data-close-dialog>Cancel</button><button id="bt-delete-strategy-confirm" class="bt-button danger">Delete strategy</button></div>');$('#bt-delete-strategy-confirm').onclick=()=>{state.strategies=state.strategies.filter(s=>s.id!==id);persist();$('#bt-dialog').close();route();};}
  });
  document.addEventListener('submit',e=>{
    if(e.target.id!=='bt-go-form')return;e.preventDefault();const s=current();if(!s)return;const t=Date.parse($('#bt-go-date').value+'Z')/1000;
    const index=s.candles.findIndex(b=>b.t>=t);
    if(index<=s.cursor || index<0){$('#bt-go-error').textContent='Choose a later date within this dataset.';return;}
    while(s.cursor<index)E.step(s);persist();$('#bt-dialog').close();updateSession();
  });
  $('#bt-guide').onclick=guide;
  $('#bt-backup').onclick=()=>download('theonepercent-backtesting-backup.json',saveBlocked ? localStorage.getItem(key) || '{}' : JSON.stringify(backup(),null,2));
  $('#bt-mobile-backup').onclick=$('#bt-backup').onclick;
  $('#bt-restore').onchange=async e=>{const file=e.target.files[0];if(!file)return;pause();try{if(file.size>20000000)throw Error('Backup must be smaller than 20 MB.');const imported=load(JSON.parse(await file.text()));modal('Restore workspace?','<p>This replaces the current browser workspace with '+imported.sessions.length+' saved sessions and '+imported.strategies.length+' strategies. Export the current workspace first if needed.</p><div class="bt-actions"><button class="bt-button" data-close-dialog>Cancel</button><button id="bt-confirm-restore" class="bt-button primary">Replace workspace</button></div>');$('#bt-confirm-restore').onclick=()=>{state=imported;saveBlocked=false;persist();$('#bt-dialog').close();location.hash='sessions';route();};}catch(error){toast(error.message);}finally{e.target.value='';}};
  window.addEventListener('hashchange',route);
  window.addEventListener('resize',()=>{if(active)drawChart();});
  window.addEventListener('beforeunload',()=>{if(ready)persist();});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){pause();if(sync)sync.flush();}});
  document.addEventListener('keydown',e=>{if(!active || $('#bt-dialog').open || /INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target.tagName) || e.ctrlKey || e.metaKey || e.altKey)return;if(e.code==='Space'){e.preventDefault();togglePlay();}if(e.code==='ArrowRight'){e.preventDefault();pause(false);advance();}});
  async function selectOwner(user) {
    const generation=++ownerGeneration;ready=false;pause(false);if(sync){sync.stop();sync=null;}if($('#bt-dialog').open)$('#bt-dialog').close();key='onepercent:backtesting:v1:'+(user?.id || 'guest');owner=user?.id?'Account':'Guest';state={sessions:[],strategies:[]};saveBlocked=false;
    try { const saved=localStorage.getItem(key);if(saved)state=load(JSON.parse(saved));$('#bt-storage-label').textContent=owner+' · saved in this browser'; }
    catch(error){saveBlocked=true;$('#bt-storage-label').textContent='Saved workspace could not be read';toast(error.message+' Export a backup or restore a valid file; the saved data was not overwritten.');}
    $('#bt-sync-login').hidden=!!user?.id;$('#bt-sync-login').href=window.OP_FLASK?'/login':ROOT+'pages/login.html';
    $('#bt-sync-status').textContent=user?.id?'Saved on this device · checking account sync':'Guest · saved on this device. Sign in to sync future account sessions.';
    $('#bt-sync-retry').hidden=true;$('#bt-sync-load').hidden=true;
    if(user?.id && window.Cloud?.client?.from && window.BacktestSync && !saveBlocked && !localMT5){
      const accountKey=key;
      sync=new window.BacktestSync({client:Cloud.client,userId:user.id,key:accountKey,storage:localStorage,getSnapshot:backup,
        applyRemote:raw=>{const imported=load(raw);state=imported;localStorage.setItem(accountKey,JSON.stringify(backup()));},
        onStatus:(status,message)=>{if(generation!==ownerGeneration)return;$('#bt-sync-status').textContent=message;$('#bt-sync-retry').hidden=!['error','conflict'].includes(status);$('#bt-sync-load').hidden=status!=='conflict';}});
      app.innerHTML='<div class="bt-empty">Loading your saved research workspace…</div>';
      await sync.start();if(generation!==ownerGeneration)return;
    }
    ready=true;route();
  }
  $('#bt-sync-login').onclick=()=>window.Cloud?.setReturn?.('backtesting',location.hash);
  $('#bt-sync-retry').onclick=async()=>{if(!sync)return;pause();await sync.start();route();};
  $('#bt-sync-load').onclick=()=>{if(!sync)return;modal('Load online workspace?','<p>This replaces the sessions on this device with your online copy. Export a workspace backup before continuing if you need to keep local changes.</p><div class="bt-actions"><button class="bt-button" data-close-dialog>Cancel</button><button class="bt-button primary" id="bt-confirm-online">Load online copy</button></div>');$('#bt-confirm-online').onclick=async()=>{$('#bt-dialog').close();await sync.start({useRemote:true});route();};};
  window.addEventListener('online',async()=>{if(sync){pause();await sync.start();route();}});
  window.addEventListener('pagehide',()=>{if(sync)sync.flush();});
  if(window.Cloud?.ready){Cloud.ready.then(selectOwner,()=>selectOwner(null));try{Cloud.client.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT')selectOwner(null);else if(event==='SIGNED_IN' && key!=='onepercent:backtesting:v1:'+session?.user?.id)selectOwner(session?.user);});}catch(_) {}}
  else selectOwner(null);
})();
